use axum::{ http::StatusCode, response::{IntoResponse, Response}, Json, }; use serde_json::json; #[derive(Debug)] pub enum AppError { NotFound(String), Unauthorized, InvalidTransition { from: String, to: String }, ValidationError(String), Database(sqlx::Error), Internal(anyhow::Error), } impl IntoResponse for AppError { fn into_response(self) -> Response { let (status, error_code, message) = match self { AppError::NotFound(msg) => (StatusCode::NOT_FOUND, "not_found", msg), AppError::Unauthorized => (StatusCode::UNAUTHORIZED, "unauthorized", "Invalid or missing API key".to_string()), AppError::InvalidTransition { from, to } => ( StatusCode::UNPROCESSABLE_ENTITY, "invalid_transition", format!("Invoice in state {} cannot transition to {}", from, to), ), AppError::ValidationError(msg) => (StatusCode::BAD_REQUEST, "validation_error", msg), AppError::Database(err) => (StatusCode::INTERNAL_SERVER_ERROR, "database_error", err.to_string()), AppError::Internal(err) => (StatusCode::INTERNAL_SERVER_ERROR, "internal_error", err.to_string()), }; let body = Json(json!({ "error": error_code, "message": message, })); (status, body).into_response() } } impl From<sqlx::Error> for AppError { fn from(err: sqlx::Error) -> Self { AppError::Database(err) } } impl From<anyhow::Error> for AppError { fn from(err: anyhow::Error) -> Self { AppError::Internal(err) } }
